/// <summary>
/// AVA FormControl AVAWorkerSalesTaker
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVAWorkerSalesTaker))]
final class AVASalesTableListPageFrmCtr_AVAWorkerSalesTaker_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret = next modified();

    FormDataSource avaSalesTable_ds = this.formRun().dataSource(tableStr(SalesTable));
    SalesTaker salesTakerLoc = this.value();

    if (salesTakerLoc)
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, WorkerSalesTaker)).value(queryValue(salesTakerLoc));
    }
    else
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, WorkerSalesTaker)).value(SysQueryRangeUtil::valueUnlimited());
    }

    avaSalesTable_ds.executeQuery();

    return ret;
}
